insert into private.tables_locataires (nom, ordre_effacement, note) values ('filed_factures', 6, 'F2'), ('filed_documents', 8, 'F1'), ('filed_fournisseurs', 25, 'F2');
insert into private.tables_objets (nom, objet_type, colonne, ordre_effacement) values ('filed_documents', 'filed_document', 'id', 90), ('filed_factures', 'filed_document', 'document_id', 20);
alter table public.filed_documents enable row level security; alter table public.filed_factures enable row level security;
grant select on all tables in schema public to authenticated, service_role;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
